  for (let z = 0; z < CS; z++) for (let x = 0; x < CS; x++) { const X = ox + x, Z = oz + z; r[z * CS + x] = clamp((N.wet.noise(X / 90, Z / 90, 5.3) + .5 * N.temp.noise(X / 35, Z / 35, 8.1)) * TINT.regional, -1, 1); }
