  for (let dz = -1; dz <= 1; dz++) for (let dx = -1; dx <= 1; dx++) grid.push(dx || dz ? chunks.get(ck(ch.cx + dx, ch.cz + dz)) : ch);
  const v = { cx: ch.cx, cz: ch.cz, maxY: ch.maxY, hv, data: new Uint8Array(n), meta: new Uint8Array(n), light: new Uint8Array(n), sky: new Uint8Array(n), region: regionTints(ch) };
  const keys = ['data', 'meta', 'light', 'sky'];
